/* ─────────────── 3. Notion ─────────────── */

async function fromNotion(url) {
  // Публичная страница отдаёт содержимое обычным HTML только частично,
  // поэтому берём то, что есть, и вытаскиваем строки, похожие на названия ролей.
  const r = await get(url);
  if (!r.text) return null;
  const text = r.text.replace(/<[^>]*>/g, '\n');
  const ROLE = /\b(head of|chief|director|cpo|cmo|cgo|cto|vp|lead|manager|specialist|engineer|designer|analyst)\b/i;
  const lines = [...new Set(text.split('\n').map(s => s.trim()).filter(s => s.length > 6 && s.length < 110 && ROLE.test(s)))];
  return lines.slice(0, 60).map(t => ({ title: t, location: '', url }));
}

/* ─────────────── общий разбор ─────────────── */

export function classify(url) {
  const u = String(url).toLowerCase();
  if (u.includes('linkedin.com')) return 'linkedin';
  if (atsFrom(url)) return 'ats';
  if (u.includes('notion.s')) return 'notion';
  if (u.includes('docs.google') || u.includes('drive.google')) return 'gdocs';
  if (/hh\.(ru|kz|uz)|headhunter|dreamjob|rabota\.by/.test(u)) return 'hh';
  return 'site';
}

