input.new_string:
/**
 * Почему страница отдала пусто. Тот же публичный эндпоинт, что и у самого сайта.
 * Возвращает 'not-public' — доступ к странице закрыт владельцем (не наша проблема
 * и не повод что-то обходить), 'deleted', либо null — причина не установлена.
 */
export async function notionAccessReason(url, fetchImpl = fetch) {
  const id = notionPageId(url);
  if (!id) return null;
  try {
    const res = await fetchImpl(`${new URL(url).origin}/api/v3/getPublicPageData`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'user-agent': UA },
      body: JSON.stringify({ type: 'block-space', name: 'page', blockId: id, saveParent: false }),
      signal: AbortSignal.timeout(20000),
    });
    if (!res.ok) return null;
    const d = await res.json();
    if (d?.isDeleted) return 'deleted';
    if (d?.publicAccessRole === 'none' && !d?.isPublicShareLink) return 'not-public';
    return null;
  } catch {
    return null;
  }
}

