      .replace(/<\/(p|div|li|h\d|ul|ol)>/gi, '\n')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

/* ─────────────── 1. We Work Remotely (RSS) ─────────────── */

const WWR_FEED = 'https://weworkremotely.com/remote-jobs.rss';
const tag = (block, name) => {
  const m = new RegExp(`<${name}\\b[^>]*>([\\s\\S]*?)</${name}>`, 'i').exec(block);
  if (!m) return '';
  const cdata = /^\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*$/.exec(m[1]);
  return (cdata ? cdata[1] : decodeEntities(m[1])).trim();
};

// Ключ дедупа — путь /remote-jobs/<slug>: в фиде и в наших ссылках он совпадает,
// а хвосты (utm, слеш) — нет.
export const wwrKey = (url) => {
  try {
    return new URL(url).pathname.replace(/\/+$/, '').toLowerCase();
  } catch {
    return '';
  }
};

/** Скачать фид один раз. Возвращает Map<путь, {title, company, text}>. */
export async function loadWwrFeed(fetchImpl = fetch) {
  const res = await fetchImpl(WWR_FEED, {
    headers: { 'user-agent': UA, accept: 'application/rss+xml,application/xml' },
    redirect: 'follow',
    signal: AbortSignal.timeout(30000),
  });
  if (!res.ok) throw new Error('WWR RSS HTTP ' + res.status);
  const xml = await res.text();
  const index = new Map();
  for (const item of xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi) || []) {
    const key = wwrKey(tag(item, 'link'));
    if (!key || key === '/remote-jobs.rss') continue;
    const title = tag(item, 'title');
    // <description> — HTML вакансии, экранированный сущностями; tag() его уже раскодировал.
    const body = htmlToText(tag(item, 'description'));
    if (!body || body.length < 300) continue;
    const head = [
      title && `# ${title}`,
      tag(item, 'region') && `Локация: ${tag(item, 'region')}`,
      tag(item, 'type') && `Занятость: ${tag(item, 'type')}`,
      tag(item, 'skills') && `Навыки: ${tag(item, 'skills')}`,
    ]
      .filter(Boolean)
      .join('\n');
    index.set(key, { title, text: `${head}\n\n${body}`.trim() });
  }
  return index;
}

/* ─────────────── 2. Notion (публичный API блоков) ─────────────── */

// 32 hex из URL -> UUID с дефисами. Берём ПОСЛЕДНИЙ такой кусок в пути:
// в /getklar/Growth-Lead-...-<id> и в /Head-of-...-<id>?v=<view> это id страницы.
export function notionPageId(url) {
  let u;
  try {
    u = new URL(url);
  } catch {
    return null;
  }
  const hits = u.pathname.match(/[0-9a-f]{32}/gi);
  if (!hits?.length) return null;
  const h = hits[hits.length - 1].toLowerCase();
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

const richText = (prop) =>
  Array.isArray(prop)
    ? prop.map((seg) => (Array.isArray(seg) ? String(seg[0] ?? '') : '')).join('')
    : '';

// В recordMap блок лежит либо как {value:{value:{...}}}, либо как {value:{...}}.
const unwrap = (rec) => {
  const v = rec?.value;
  return (v && typeof v === 'object' && v.value) || v || null;
};

const PREFIX = {
  header: '\n## ',
  sub_header: '\n### ',
  sub_sub_header: '\n#### ',
  bulleted_list: '• ',
  numbered_list: '• ',
  to_do: '• ',
  toggle: '',
  quote: '> ',
};

/** Обойти дерево блоков в порядке content и собрать текст. */
function renderBlocks(blocks, rootId) {
  const out = [];
  const seen = new Set();
  const walk = (id, depth) => {
    if (!id || seen.has(id) || depth > 12) return;
    seen.add(id);
    const b = unwrap(blocks[id]);
    if (!b) return;
    const title = richText(b.properties?.title);
    if (title) out.push((PREFIX[b.type] ?? '') + title);
    for (const child of b.content || []) walk(child, depth + 1);
  };
  walk(rootId, 0);
  return out
    .join('\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Текст публичной Notion-страницы. null — если страницы нет или содержимое пустое. */
export async function fetchNotionText(url, fetchImpl = fetch) {
  const id = notionPageId(url);
  if (!id) return null;
  const origin = new URL(url).origin;
  const res = await fetchImpl(`${origin}/api/v3/loadCachedPageChunkV2`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'user-agent': UA },
    body: JSON.stringify({
      page: { id },
      limit: 200,
      cursor: { stack: [] },
      chunkNumber: 0,
      verticalColumns: false,
    }),
    signal: AbortSignal.timeout(30000),
  });
  if (!res.ok) throw new Error('Notion API HTTP ' + res.status);
  const data = await res.json();
  const blocks = data?.recordMap?.block;
  if (!blocks) return null;
  const text = renderBlocks(blocks, id);
  return text || null;
}
