// Фид WWR тянется один раз на весь прогон и только если он реально нужен.
let wwrFeed=null;
if(todo.some(r=>/(^|\.)weworkremotely\.com$/i.test(hostOf(r.url)))){
  try{ wwrFeed=await special.loadWwrFeed(); console.log(`фид weworkremotely: ${wwrFeed.size} вакансий с текстом`); }
  catch(e){ console.log('фид weworkremotely недоступен: '+e.message); wwrFeed=new Map(); }
}

// Возвращает {text} при успехе, {skip:'причина'} — если источник взять нельзя,
// либо null — если для этого хоста особого пути нет и работает общий GET.
async function fetchSpecial(url){
  const host=hostOf(url);
  if(/(^|\.)weworkremotely\.com$/i.test(host)){
    // Страница вакансии закрыта Cloudflare-челленджем (403, cf-mitigated: challenge).
    // Челлендж не обходим: текст берём из публичного RSS этой же площадки.
    const hit=wwrFeed?.get(special.wwrKey(url));
    return hit ? {text:hit.text} : {skip:'нет в RSS-фиде (фид отдаёт только свежую выдачу)'};
  }
  if(/(^|\.)notion\.site$/i.test(host)){
    // Не защита, а рендеринг: содержимое отдаёт публичный API блоков Notion.
    const text=await special.fetchNotionText(url);
    if(text) return {text};
    const why=await special.notionAccessReason(url);
    return {skip: why==='not-public' ? 'страница больше не опубликована владельцем'
          : why==='deleted' ? 'страница удалена' : 'API вернул пустое содержимое'};
  }
  return null;
}

