// Unit tests for jd-fetch-special.mjs — the two sources that a plain GET cannot
// reach: weworkremotely (Cloudflare challenge on the job page → public RSS instead)
// and *.notion.site (JS-rendered shell → the page's own public block API).
// Parser-level only, no network: fetch is stubbed.
// Run: node tests/jd-fetch-special.test.mjs
import assert from 'node:assert/strict';
import { loadWwrFeed, wwrKey, notionPageId, fetchNotionText } from '../jd-fetch-special.mjs';

let passed = 0;
const t = (name, fn) => { fn(); passed++; console.log(`  ✓ ${name}`); };
const ta = async (name, fn) => { await fn(); passed++; console.log(`  ✓ ${name}`); };

// ---- wwrKey: the dedup key is the path, so query junk and trailing slash don't matter ----
t('wwrKey normalizes path, drops query and trailing slash', () => {
  const k = '/remote-jobs/acme-head-of-marketing';
  assert.equal(wwrKey('https://weworkremotely.com/remote-jobs/acme-head-of-marketing'), k);
  assert.equal(wwrKey('https://weworkremotely.com/remote-jobs/acme-head-of-marketing/'), k);
  assert.equal(wwrKey('https://weworkremotely.com/remote-jobs/acme-head-of-marketing?utm_source=x'), k);
  assert.equal(wwrKey('not a url'), '');
});

// ---- loadWwrFeed ----
const long = 'We are looking for a hands-on marketer. '.repeat(20);
const FEED = `<rss><channel>
<item>
  <title>Acme: Head of Marketing</title>
  <link>https://weworkremotely.com/remote-jobs/acme-head-of-marketing</link>
  <region>Anywhere in the World</region>
  <type>Full-Time</type>
  <skills>SEO, Email</skills>
  <description>&lt;p&gt;${long}&lt;/p&gt;&lt;ul&gt;&lt;li&gt;Own the funnel&lt;/li&gt;&lt;/ul&gt;</description>
</item>
<item>
  <title>Tiny: Intern</title>
  <link>https://weworkremotely.com/remote-jobs/tiny-intern</link>
  <description>&lt;p&gt;too short&lt;/p&gt;</description>
</item>
</channel></rss>`;

const stubFetch = (body, { ok = true, status = 200 } = {}) => async () => ({
  ok, status,
  text: async () => body,
  json: async () => JSON.parse(body),
});

await ta('loadWwrFeed indexes items by path and keeps the full description', async () => {
  const idx = await loadWwrFeed(stubFetch(FEED));
  const hit = idx.get('/remote-jobs/acme-head-of-marketing');
  assert.ok(hit, 'item should be indexed by its path');
  assert.equal(hit.title, 'Acme: Head of Marketing');
  assert.match(hit.text, /^# Acme: Head of Marketing/);
  assert.match(hit.text, /Локация: Anywhere in the World/);
  assert.match(hit.text, /hands-on marketer/);
  assert.match(hit.text, /• Own the funnel/, 'list items survive as bullets');
  assert.doesNotMatch(hit.text, /&lt;|<p>/, 'HTML and entities are decoded away');
});

await ta('loadWwrFeed drops items whose description is too short to be a JD', async () => {
  const idx = await loadWwrFeed(stubFetch(FEED));
  assert.equal(idx.has('/remote-jobs/tiny-intern'), false);
  assert.equal(idx.size, 1);
});

await ta('loadWwrFeed surfaces a bad feed response instead of returning empty', async () => {
  await assert.rejects(() => loadWwrFeed(stubFetch('', { ok: false, status: 503 })), /HTTP 503/);
});

// ---- notionPageId: the page id is the LAST 32-hex run in the path ----
t('notionPageId takes the trailing id, ignoring ?v= view ids and /workspace/ prefixes', () => {
  assert.equal(
    notionPageId('https://simbel.notion.site/Marketing-Lead-a203671c9d4a4fe6afddaafeb56c4ece?pvs=25'),
    'a203671c-9d4a-4fe6-afdd-aafeb56c4ece');
  // ?v= is a view id in the query, not the path — it must not win.
  assert.equal(
    notionPageId('https://heva.notion.site/Head-of-Marketing-3ba4d306509080359940d89d2e84b93b?v=2444d306509081549b3c000c21684e85'),
    '3ba4d306-5090-8035-9940-d89d2e84b93b');
  // /getklar/ prefix before the slug.
  assert.equal(
    notionPageId('https://getklar.notion.site/getklar/Growth-Lead-d691a39aa0d943a48f14ee5ac010cbc2?pvs=25'),
    'd691a39a-a0d9-43a4-8f14-ee5ac010cbc2');
  assert.equal(notionPageId('https://getklar.notion.site/careers'), null);
  assert.equal(notionPageId('nonsense'), null);
});

// ---- fetchNotionText: walk the recordMap in content order ----
const ID = 'a203671c-9d4a-4fe6-afdd-aafeb56c4ece';
const blk = (id, type, title, content) => ({
  [id]: { value: { value: { id, type, properties: title ? { title: [[title]] } : {}, content } } },
});
const RECORD_MAP = JSON.stringify({
  recordMap: {
    block: {
      ...blk(ID, 'page', 'Marketing Lead', ['b1', 'b2', 'b3']),
      ...blk('b1', 'sub_header', 'Le rôle'),
      ...blk('b2', 'bulleted_list', 'Profile: >3y in SaaS B2B', ['b2a']),
      ...blk('b2a', 'bulleted_list', 'Package: 70-90k€'),
      // Unwrapped shape {value:{...}} also occurs in real responses.
      b3: { value: { id: 'b3', type: 'text', properties: { title: [['Based in Paris 6e']] } } },
    },
  },
});

await ta('fetchNotionText renders blocks depth-first with type prefixes', async () => {
  const text = await fetchNotionText(`https://simbel.notion.site/Marketing-Lead-${ID.replace(/-/g, '')}`, stubFetch(RECORD_MAP));
  assert.match(text, /Marketing Lead/);
  assert.match(text, /### Le rôle/);
  assert.match(text, /• Profile: >3y in SaaS B2B/);
  assert.match(text, /• Package: 70-90k€/, 'nested children are followed');
  assert.match(text, /Based in Paris 6e/, 'the {value:{...}} block shape is handled');
  // Order must follow `content`, not object key order.
  assert.ok(text.indexOf('Le rôle') < text.indexOf('Profile'));
});

await ta('fetchNotionText returns null on an empty recordMap rather than a fake hit', async () => {
  const empty = JSON.stringify({ recordMap: {} });
  assert.equal(await fetchNotionText(`https://heva.notion.site/x-${ID.replace(/-/g, '')}`, stubFetch(empty)), null);
});

await ta('fetchNotionText returns null when the URL carries no page id', async () => {
  assert.equal(await fetchNotionText('https://heva.notion.site/careers', stubFetch(RECORD_MAP)), null);
});

console.log(`\njd-fetch-special: ${passed} passed`);

